import re
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Tuple
from urllib.parse import urlparse


@dataclass
class RobotsRule:
    path: str
    allowed: bool

    def matches(self, request_path: str) -> bool:
        if not request_path.startswith("/"):
            request_path = "/" + request_path
        if self.path == "/":
            return True
        if self.path.endswith("*") and request_path.startswith(self.path[:-1]):
            return True
        if request_path.startswith(self.path):
            return True
        if self.path.endswith("$") and request_path == self.path[:-1]:
            return True
        if self.path.endswith("$"):
            return False
        return request_path.startswith(self.path)

    def __len__(self):
        return len(self.path.rstrip("$*"))


@dataclass
class UserAgentBlock:
    user_agents: List[str]
    rules: List[RobotsRule] = field(default_factory=list)
    crawl_delay: Optional[float] = None

    def is_allowed(self, path: str) -> bool:
        best_match: Optional[RobotsRule] = None
        best_len = -1
        for rule in self.rules:
            if rule.matches(path):
                rule_len = len(rule)
                if rule_len > best_len:
                    best_len = rule_len
                    best_match = rule
        if best_match is None:
            return True
        return best_match.allowed


class RobotsParser:

    _GROUP_START = re.compile(r"^\s*[Uu][Ss][Ee][Rr]\s*-\s*[Aa][Gg][Ee][Nn][Tt]\s*:\s*(.*)$")
    _RULE_ALLOW = re.compile(r"^\s*[Aa][Ll][Ll][Oo][Ww]\s*:\s*(.*)$")
    _RULE_DISALLOW = re.compile(r"^\s*[Dd][Ii][Ss][Aa][Ll][Ll][Oo][Ww]\s*:\s*(.*)$")
    _CRAWL_DELAY = re.compile(r"^\s*[Cc][Rr][Aa][Ww][Ll]\s*-\s*[Dd][Ee][Ll][Aa][Yy]\s*:\s*(.*)$")
    _SITEMAP = re.compile(r"^\s*[Ss][Ii][Tt][Ee][Mm][Aa][Pp]\s*:\s*(.*)$")

    def __init__(self, robots_txt: str, fetch_time: Optional[float] = None):
        self.raw = robots_txt
        self.fetch_time = fetch_time
        self.blocks: List[UserAgentBlock] = []
        self.default_block: Optional[UserAgentBlock] = None
        self.sitemaps: List[str] = []
        self._parse(robots_txt)

    def _parse(self, text: str):
        text = text.lstrip("\ufeff")
        lines = text.splitlines()
        current_block: Optional[UserAgentBlock] = None

        for line in lines:
            line = line.strip()
            if not line or line.startswith("#"):
                continue

            m = self._GROUP_START.match(line)
            if m:
                agents = [a.strip() for a in m.group(1).split(",")]
                current_block = UserAgentBlock(user_agents=agents)
                for agent in agents:
                    if agent.strip() == "*":
                        self.default_block = current_block
                self.blocks.append(current_block)
                continue

            if current_block is None:
                current_block = UserAgentBlock(user_agents=["*"])
                self.default_block = current_block
                self.blocks.append(current_block)

            m = self._RULE_DISALLOW.match(line)
            if m:
                path = m.group(1).strip()
                if path:
                    current_block.rules.append(RobotsRule(path=path, allowed=False))
                continue

            m = self._RULE_ALLOW.match(line)
            if m:
                path = m.group(1).strip()
                if path:
                    current_block.rules.append(RobotsRule(path=path, allowed=True))
                continue

            m = self._CRAWL_DELAY.match(line)
            if m:
                try:
                    current_block.crawl_delay = float(m.group(1).strip())
                except ValueError:
                    pass
                continue

            m = self._SITEMAP.match(line)
            if m:
                self.sitemaps.append(m.group(1).strip())

    def _find_block(self, user_agent: str) -> Optional[UserAgentBlock]:
        user_agent_lower = user_agent.lower()
        best_match = None
        longest_len = -1

        for block in self.blocks:
            for agent in block.user_agents:
                agent_lower = agent.lower()
                if agent == "*":
                    if best_match is None:
                        best_match = block
                    continue
                if agent_lower in user_agent_lower or user_agent_lower in agent_lower:
                    if len(agent_lower) > longest_len:
                        longest_len = len(agent_lower)
                        best_match = block

        return best_match or self.default_block

    def is_allowed(self, url: str, user_agent: str = "*") -> bool:
        try:
            parsed = urlparse(url)
            path = parsed.path or "/"
            if parsed.query:
                path += "?" + parsed.query
        except Exception:
            return True

        block = self._find_block(user_agent)
        if block is None:
            return True

        return block.is_allowed(path)

    def get_crawl_delay(self, user_agent: str = "*") -> Optional[float]:
        block = self._find_block(user_agent)
        if block:
            return block.crawl_delay
        return None

    def get_sitemaps(self) -> List[str]:
        return list(self.sitemaps)

    def __repr__(self):
        return f"RobotsParser(blocks={len(self.blocks)}, sitemaps={len(self.sitemaps)})"


class RobotsCache:
    def __init__(self, ttl: float = 3600):
        self._cache: Dict[str, Tuple[RobotsParser, float]] = {}
        self._ttl = ttl

    def get(self, domain: str) -> Optional[RobotsParser]:
        import time
        entry = self._cache.get(domain)
        if entry is None:
            return None
        parser, timestamp = entry
        if time.time() - timestamp > self._ttl:
            del self._cache[domain]
            return None
        return parser

    def set(self, domain: str, parser: RobotsParser):
        import time
        self._cache[domain] = (parser, time.time())

    def invalidate(self, domain: str):
        self._cache.pop(domain, None)

    def __len__(self):
        import time
        now = time.time()
        valid = sum(1 for _, ts in self._cache.values() if now - ts <= self._ttl)
        return valid

import hashlib
import heapq
import time
import math
from dataclasses import dataclass, field
from typing import Dict, Iterator, List, Optional, Set, Tuple
from collections import defaultdict


@dataclass(order=True)
class FrontierItem:
    priority: int
    url: str = field(compare=False)
    domain: str = field(compare=False)
    added_at: float = field(default_factory=time.time, compare=False)
    depth: int = field(default=0, compare=False)


class URLFrontier:
    def __init__(self, politeness_manager=None, max_size: int = 100_000_000):
        self._heap: List[FrontierItem] = []
        self._url_set: Set[str] = set()
        self._domain_locks: Dict[str, bool] = defaultdict(bool)
        self._domain_queues: Dict[str, List[FrontierItem]] = defaultdict(list)
        self._politeness_manager = politeness_manager
        self._max_size = max_size
        self._crawled_count: int = 0
        self._failed_count: int = 0

    def push(self, url: str, priority: int = 0, depth: int = 0, domain: Optional[str] = None) -> bool:
        if len(self._url_set) >= self._max_size:
            return False
        if url in self._url_set:
            return False

        if domain is None:
            from urllib.parse import urlparse
            domain = urlparse(url).netloc.lower() or "unknown"

        item = FrontierItem(priority=priority, url=url, domain=domain, depth=depth)
        self._url_set.add(url)
        heapq.heappush(self._heap, item)
        self._domain_queues[domain].append(item)
        return True

    def pop(self) -> Optional[FrontierItem]:
        while self._heap:
            item = heapq.heappop(self._heap)
            if item.url not in self._url_set:
                continue
            if self._politeness_manager and not self._politeness_manager.can_request(item.domain):
                heapq.heappush(self._heap, item)
                continue
            self._url_set.discard(item.url)
            return item
        return None

    def pop_batch(self, max_count: int = 10) -> List[FrontierItem]:
        seen_domains: Set[str] = set()
        batch: List[FrontierItem] = []
        temp: List[FrontierItem] = []

        while self._heap and len(batch) < max_count:
            item = heapq.heappop(self._heap)
            if item.url not in self._url_set:
                continue
            if item.domain in seen_domains:
                temp.append(item)
                continue
            if self._politeness_manager and not self._politeness_manager.can_request(item.domain):
                temp.append(item)
                continue
            self._url_set.discard(item.url)
            seen_domains.add(item.domain)
            batch.append(item)

        for item in temp:
            heapq.heappush(self._heap, item)

        return batch

    def mark_crawled(self, url: str):
        self._crawled_count += 1

    def mark_failed(self, url: str):
        self._failed_count += 1

    def __len__(self) -> int:
        return len(self._url_set)

    def __bool__(self) -> bool:
        return len(self._url_set) > 0

    def size(self) -> int:
        return len(self._url_set)

    def empty(self) -> bool:
        return len(self._url_set) == 0

    def peek_domain_distribution(self) -> Dict[str, int]:
        return {d: len(q) for d, q in self._domain_queues.items()}

    @property
    def crawled_count(self) -> int:
        return self._crawled_count

    @property
    def failed_count(self) -> int:
        return self._failed_count


class DistributedFrontier(URLFrontier):
    def __init__(self, redis_client=None, shard_count: int = 16, **kwargs):
        super().__init__(**kwargs)
        self._redis = redis_client
        self._shard_count = shard_count

    def _get_shard(self, url: str) -> int:
        h = hashlib.md5(url.encode()).digest()
        return int.from_bytes(h[:4], "big") % self._shard_count

    def push(self, url: str, priority: int = 0, depth: int = 0, domain: Optional[str] = None) -> bool:
        if self._redis:
            shard = self._get_shard(url)
            key = f"frontier:shard:{shard}"
            self._redis.zadd(key, {url: priority})
            return True
        return super().push(url, priority, depth, domain)

    def pop(self) -> Optional[FrontierItem]:
        if self._redis:
            for shard in range(self._shard_count):
                key = f"frontier:shard:{shard}"
                results = self._redis.zpopmin(key, 1)
                if results:
                    url, priority = results[0]
                    return FrontierItem(priority=priority, url=url, domain="")
            return None
        return super().pop()
